-- Upgrade databases created before integer primary keys were changed to
-- GENERATED BY DEFAULT AS IDENTITY. Safe to run on fresh schemas as well.
DO $$
DECLARE
    table_name_value text;
    identity_state text;
BEGIN
    FOREACH table_name_value IN ARRAY ARRAY[
        'auditoriums',
        'movies',
        'screenings',
        'seats',
        'bookings',
        'payment_attempts',
        'payment_initializations',
        'webhook_inbox'
    ] LOOP
        SELECT is_identity
        INTO identity_state
        FROM information_schema.columns
        WHERE table_schema = current_schema()
          AND table_name = table_name_value
          AND column_name = 'id';

        IF identity_state IS NULL THEN
            RAISE EXCEPTION 'Expected %.% id column was not found', current_schema(), table_name_value;
        ELSIF identity_state = 'NO' THEN
            EXECUTE format(
                'ALTER TABLE %I.%I ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY',
                current_schema(), table_name_value
            );
        ELSE
            EXECUTE format(
                'ALTER TABLE %I.%I ALTER COLUMN id SET GENERATED BY DEFAULT',
                current_schema(), table_name_value
            );
        END IF;

        EXECUTE format(
            'SELECT setval(pg_get_serial_sequence(%L, %L)::regclass, COALESCE(MAX(id), 1), MAX(id) IS NOT NULL) FROM %I.%I',
            format('%I.%I', current_schema(), table_name_value),
            'id',
            current_schema(),
            table_name_value
        );
    END LOOP;
END $$;
